GimCorpus.put(106,0,[[1,1,"וַיְהִי בִּימֵי אֲחַשְׁוֵרוֹשׁ. מֶלֶךְ פָּרַס הָיָה, שֶׁמָּלַךְ תַּחַת כּוֹרֶשׁ לְסוֹף שִׁבְעִים שָׁנָה שֶׁל גָּלוּת בָּבֶל:",1,0],[1,1,"הוּא אֲחַשְׁוֵרוֹשׁ. הוּא בְרִשְׁעוֹ מִתְּחִלָּתוֹ וְעַד סוֹפוֹ:",2,0],[1,1,"הַמֹּלֵךְ. שֶׁמָּלַךְ מֵעַצְמוֹ וְלֹא הָיָה מִזֶּרַע הַמְּלוּכָה:",3,0],[1,1,"מֵהֹדּוּ וְעַד כּוּשׁ, וגו'. הַמּוֹלֵךְ עַל מֵאָה וְעֶשְׂרִים וְשֶׁבַע מְדִינוֹת כְּמוֹ שֶׁמָּלַךְ מֵהֹדוּ וְעַד כּוּשׁ שֶׁעוֹמְדִים זֶה אֵצֶל זֶה. וְכֵן \"כִּי הוּא רֹדֶה בְּכָל עֵבֶר הַנָּהָר מִתִּפְסַח וְעַד עַזָּה\", שֶׁהָיָה רוֹדֶה בְּכָל עֵבֶר הַנָּהָר כְּמוֹ שֶׁהוּא רוֹדֶה מִתִּפְסַח עַד עַזָּה:",4,0],[1,2,"כְּשֶׁבֶת הַמֶּלֶךְ אֲחַשְׁוֵרוֹשׁ, וגו'. כְּשֶׁנִּתְקַיֵּם הַמַּלְכוּת בְּיָדוֹ. וְרַבּוֹתֵינוּ פֵּרְשׁוּהוּ בְּעִנְיָן אַחֵר בְּמַסֶּכֶת מְגִילָּה:",1,0],[1,3,"הַפַּרְתְּמִים. שִׁלְטוֹנִים בִּלְשׁוֹן פָּרַס:",1,0],[1,4,"יָמִים רַבִּים. עָשָׂה לָהֶם מִשְׁתֶּה:",1,0],[1,5,"גִּנַּת. מְקוֹם זֵרְעוֹנֵי יְרָקוֹת:",1,0],[1,5,"בִּיתַן. נָטוּעַ בְּאִילָנוֹת:",2,0],[1,6,"חוּר כַּרְפַּס וּתְכֵלֶת. מִינֵי בְגָדִים צִבְעוֹנִים פֵּרַס לָהֶם לְמַצָּעוֹת:",1,0],[1,6,"אָחוּז בְּחַבְלֵי בוּץ וְאַרְגָּמָן. מְרֻקָּמִים בִּפְתִילֵי בוּץ וְאַרְגָּמָן. אוֹתָן פֵּרַס לָהֶם עַל גְּלִילֵי כֶסֶף וְעַל עַמּוּדֵי שֵׁשׁ:",2,0],[1,6,"מִטּוֹת זָהָב וָכֶסֶף. עָרַךְ לֵישֵׁב עֲלֵיהֶם לִסְעוּדָה:",3,0],[1,6,"עַל רִצְפַת. קַרְקָעוֹת שֶׁל בַּהַט וָשֵׁשׁ, וגו'. מִינֵי אֲבָנִים טוֹבוֹת פֵּרְשׁוּ רַבּוֹתֵינוּ. וּלְפִי מַשְׁמָעוּת הַמִּקְרָא כַּךְ שְׁמָם:",4,0],[1,7,"וְהַשְׁקוֹת בִּכְלֵי זָהָב. כְּמוֹ וּלְהַשְׁקוֹת:",1,0],[1,7,"שׁוֹנִים. מְשֻׁנִּים זֶה מִזֶּה, וְכֵן \"וְדָתֵיהֶם שֹׁנוֹת\". וְרַבּוֹתֵינוּ דָרְשׁוּ מַה שֶׁדָּרְשׁוּ:",2,0],[1,7,"וְיֵין מַלְכוּת רָב. הַרְבֵּה. וְרַבּוֹתֵינוּ אָמְרוּ: שֶׁהִשְׁקָה אוֹתָם כָּל אֶחָד וְאֶחָד יַיִן שֶׁהוּא זָקֵן מִמֶּנּוּ:",3,0],[1,8,"כַדָּת. לְפִי שֶׁיֵּשׁ סְעוּדוֹת שֶׁכּוֹפִין אֶת הַמְּסֻבִּין לִשְׁתּוֹת כְּלִי גָדוֹל, וְיֵשׁ שֶׁאֵינוֹ יָכוֹל לִשְׁתּוֹתוֹ כִּי אִם בְּקֹשִׁי, אֲבָל כַּאן: \"אֵין אוֹנֵס\":",1,0],[1,8,"יִסַּד. לְשׁוֹן יְסוֹד, כְּלוֹמַר, כֵּן תִּקֵּן וְצִוָּה:",2,0],[1,8,"עַל כָּל רַב בֵּיתוֹ. עַל כָּל שָׂרֵי הַסְּעוּדָה, שַׂר הָאוֹפִים וְשַׂר הַטַּבָּחִים וְשַׂר הַמַּשְׁקִים:",3,0],[1,8,"לַעֲשׂוֹת כִּרְצוֹן אִישׁ וָאִישׁ. לְכָל אֶחָד וְאֶחָד רְצוֹנוֹ:",4,0],[1,10,"בַּיּוֹם הַשְּׁבִיעִי. רַבּוֹתֵינוּ אָמְרוּ: שַׁבָּת הָיָה:",1,0],[1,12,"וַתְּמָאֵן הַמַּלְכָּה וַשְׁתִּי. רַבּוֹתֵינוּ אָמְרוּ: לְפִי שֶׁפָּרְחָה בָהּ צָרַעַת כְּדֵי שֶׁתְּמָאֵן וְתֵהָרֵג. לְפִי שֶׁהָיְתָה מַפְשֶׁטֶת בְּנוֹת יִשְׂרָאֵל עֲרֻמּוֹת וְעוֹשָׂה בָהֶן מְלָאכָה בַּשַּׁבָּת, נִגְזַר עָלֶיהָ שֶׁתִּפָּשֵׁט עֲרֻמָּה בַּשַּׁבָּת:",1,0],[1,12,"וַיִּקְצֹף. שֶׁשָּׁלְחָה לוֹ דִבְרֵי גְנַאי:",2,0],[1,13,"כִּי כֵן דְּבַר הַמֶּלֶךְ. כִּי כֵן מִנְהַג הַמֶּלֶךְ בְּכָל מִשְׁפָּט לָשׂוּם אֶת הַדָּבָר \"לִפְנֵי כָּל יוֹדְעֵי דָּת וָדִין\":",1,0],[1,14,"וְהַקָּרֹב אֵלָיו. לַעֲרֹךְ דְּבָרָיו לִפְנֵיהֶם. אֵלּוּ הֵם: כַּרְשְׁנָא שֵׁתָר, וגו':",1,0],[1,15,"כְּדָת מַה לַּעֲשׂוֹת. מוּסָב עַל \"וַיֹּאמֶר הַמֶּלֶךְ לַחֲכָמִים\":",1,0],[1,16,"עָוְתָה. לְשׁוֹן עָו‍ֹן:",1,0],[1,17,"כִּי יֵצֵא דְבַר הַמַּלְכָּה עַל כָּל הַנָּשִׁים. זֶה שֶׁבִּזְּתָה אֶת הַמֶּלֶךְ עַל כָּל הַנָּשִׁים לְהַבְזוֹת אַף הֵן אֶת בַּעֲלֵיהֶן:",1,0],[1,18,"תֹּאמַרְנָה שָׂרוֹת פָּרַס וּמָדַי וגו'. לְכֹל שָׂרֵי הַמֶּלֶךְ אֶת הַדָּבָר הַזֶּה. וַהֲרֵי זֶה מִקְרָא קָצֵר:",1,0],[1,18,"וּכְדַי בִּזָּיוֹן. וְיֵשׁ בַּדָּבָר הַזֶּה הַרְבֵּה בִזָּיוֹן וָקָצֶף:",2,0],[1,19,"דְבַר מַלְכוּת. גְּזֵרַת מַלְכוּת שֶׁל נְקָמָה שֶׁצִּוָּה לְהָרְגָהּ:",1,0],[1,19,"וְיִכָּתֵב בְּדָתֵי פָרַס וּמָדַי. בְּסִפְרֵי חֹק וּמִנְהַג הַמַּלְכוּת:",2,0],[1,19,"וְלֹא יַעֲבוֹר. חוֹק זֶה מִבֵּינֵיהֶם שֶׁיְּהֵא זֶה חוֹק וְדָת לְכָל הַבּוֹזָה אֶת בַּעְלָהּ:",3,0],[1,19,"אֲשֶׁר לֹא תָבוֹא וַשְׁתִּי. וּלְכַךְ נֶהֶרְגָה:",4,0],[1,22,"וּמְדַבֵּר כִּלְשׁוֹן עַמּוֹ. כּוֹפֶה אֶת אִשְׁתּוֹ לִלְמֹד אֶת לְשׁוֹנוֹ אִם הִיא בַּת לָשׁוֹן אַחֵר:",1,0],[2,1,"זָכַר אֶת וַשְׁתִּי. אֶת יָפְיָהּ וְנֶעֱצַב:",1,0],[2,3,"וְיַפְקֵד הַמֶּלֶךְ פְּקִידִים. לְפִי שֶׁכָּל פָּקִיד וּפָקִיד יְדוּעוֹת לוֹ נָשִׁים הַיָּפוֹת שֶׁבִּמְדִינָתוֹ:",1,0],[2,3,"תַּמְרֻקֵיהֶן. הֵן דְּבָרִים הַמְצַחְצְחִין כְּמוֹ \"וּמֹרַק וְשֻׁטַּף.\" שֶׁמֶן עָרֵב וּמִינֵי סַמָּנִים וּבְשָׂמִים הַמְטַהֲרִין וּמְעַדְּנִין אֶת הַבָּשָׂר:",2,0],[2,5,"אִישׁ יְהוּדִי. עַל שֶׁגָּלָה עִם גָּלוּת יְהוּדָה. כָּל אוֹתָן שֶׁגָּלוּ עִם מַלְכֵי יְהוּדָה הָיוּ קְרוּיִים \"יְהוּדִים\" בֵּין הַגּוֹיִם, וַאֲפִילוּ מִשֵּׁבֶט אַחֵר הֵם:",1,0],[2,5,"אִישׁ יְמִינִי. מִבִּנְיָמִין הָיָה, כַּךְ פְּשׁוּטוֹ. וְרַבּוֹתֵינוּ דָרְשׁוּ מַה שֶׁדָּרְשׁוּ:",2,0],[2,7,"לוֹ לְבַת. רַבּוֹתֵינוּ פֵּרְשׁוּ \"לְבַיִת\", לְאִשָּׁה:",1,0],[2,9,"וַיְבַהֵל אֶת תַּמְרוּקֶיהָ. זָרִיז וּמְמַהֵר בְּשֶׁלָּהּ, מִשֶּׁל כֻּלָּן:",1,0],[2,9,"הָרְאֻיוֹת לָתֶת לָהּ. לְשָׁרְתָהּ, וְכֵן עוֹשִׂין לְכֻלָּן. וְרַבּוֹתֵינוּ דָרְשׁוּ מַה שֶּׁדָּרְשׁוּ:",2,0],[2,9,"וַיְשַׁנֶּהָ. שִׁנָּה אוֹתָהּ:",3,0],[2,10,"אֲשֶׁר לֹא תַגִּיד. כְּדֵי שֶׁיֹּאמְרוּ שֶׁהִיא מִמִּשְׁפָּחָה בְזוּיָה וִישַׁלְּחוּהָ, שֶׁאִם יֵדְעוּ שֶׁהִיא מִמִּשְׁפַּחַת שָׁאוּל הַמֶּלֶךְ הָיוּ מַחֲזִיקִים בָּהּ:",1,0],[2,11,"וּמַה יֵּעָשֶׂה בָּהּ. זֶה אֶחָד מִשְּׁנֵי צַדִּיקִים שֶׁנִּתַּן לָהֶם רֶמֶז יְשׁוּעָה: דָּוִד וּמָרְדְּכַי. דָּוִד, שֶׁנֶּאֱמַר \"גַּם אֶת הָאֲרִי גַּם אֶת הַדּוֹב הִכָּה עַבְדֶּךָ\". אָמַר: \"לֹא בָא לְיָדִי דָבָר זֶה אֶלָּא לִסְמֹךְ עָלָיו לְהִלָּחֵם עִם זֶה\". וְכֵן מָרְדְּכַי אָמַר: \"לֹא אֵרַע לְצַדֶּקֶת זוּ שֶׁתִּלָּקַח לְמִשְׁכַּב נָכְרִי אֶלָּא שֶׁעֲתִידָה לָקוּם לְהוֹשִׁיעַ לְיִשְׂרָאֵל\". לְפִיכָךְ, הָיָה מְחַזֵּר לָדַעַת מַה יְּהֵא בְסוֹפָהּ:",1,0],[2,12,"תֹּר. זְמַן:",1,0],[2,13,"כָּל אֲשֶׁר תֹּאמַר. כָּל שְׂחוֹק וּמִינֵי זֶמֶר:",1,0],[2,14,"אֶל בֵּית הַנָּשִׁים שֵׁנִי. הַשֵּׁנִי:",1,0],[2,16,"בַּחֹדֶשׁ הָעֲשִׂירִי. עֵת צִנָּה שֶׁהַגּוּף נֶהֱנֶה מִן הַגּוּף. זִמֵּן הַקָּדוֹשׁ בָּרוּךְ הוּא אוֹתוֹ עֵת צִנָּה כְּדֵי לְחַבְּבָהּ עָלָיו:",1,0],[2,17,"מִכָּל הַנָּשִׁים. הַבְּעוּלוֹת, שֶׁאַף נָשִׁים הַבְּעוּלוֹת קִבֵּץ:",1,0],[2,18,"וַהֲנָחָה לַמְּדִינוֹת עָשָׂה. לִכְבוֹדָהּ הֵנִיחַ לָהֶם מִן הַמַּס שֶׁעֲלֵיהֶם:",1,0],[2,18,"וַיִּתֵּן מַשְׂאֵת. שָׁלַח דּוֹרוֹנוֹת לָהֶם. וְהַכֹּל כְּדֵי לְפַתּוֹתָהּ אוּלַי תַּגִּיד מוֹלַדְתָּהּ. וְאַף עַל פִּי כֵן:",2,0],[2,20,"אֵין אֶסְתֵּר מַגֶּדֶת מוֹלַדְתָּהּ. לְפִי שֶׁמָּרְדְּכַי יוֹשֵׁב בְּשַׁעַר הַמֶּלֶךְ, הַמְזָרְזָהּ וְהַמְרַמְּזָהּ עַל כָּךְ:",1,0],[2,21,"לִשְׁלֹחַ יָד. לְהַשְׁקוֹתוֹ סַם הַמָּוֶת:",1,0],[2,22,"וַיִּוָּדַע הַדָּבָר לְמָרְדְּכַי. שֶׁהָיוּ מְסַפְּרִים דִּבְרֵיהֶם לְפָנָיו בְּלָשׁוֹן טוּרְסִי, וְאֵין יוֹדְעִים שֶׁהָיָה מָרְדְּכַי מַכִּיר בְּשִׁבְעִים לְשׁוֹנוֹת שֶׁהָיָה מִיּוֹשְׁבֵי לִשְׁכַּת הַגָּזִית:",1,0],[2,23,"וַיִּכָּתֵב בְּסֵפֶר דִּבְרֵי הַיָּמִים. הַטּוֹבָה שֶׁעָשָׂה מָרְדְּכַי לַמֶּלֶךְ:",1,0],[3,1,"אַחַר הַדְּבָרִים הָאֵלֶּה. שֶׁנִבְרֵאת רְפוּאָה זוּ לִהְיוֹת לִתְשׁוּעָה לְיִשְׂרָאֵל:",1,0],[3,1,"גִּדַּל הַמֶּלֶךְ וְגוֹ' אֶת הָמָן. שֶׁהַקָּדוֹשׁ בָּרוּךְ הוּא בּוֹרֵא רְפוּאָה לְמַכָּתָן שֶׁל יִשְׂרָאֵל קוֹדֶם שֶׁיָבִיא הַמַּכָּה עֲלֵיהֶם:",2,0],[3,2,"כֹּרְעִים וּמִשְׁתַּחֲוִים. שֶׁעָשָׂה עַצְמוֹ אֱלוֹהַּ, לְפִיכָךְ, וּמָרְדְּכַי לֹא יִכְרַע וְלֹא יִשְׁתַּחֲוֶה:",1,0],[3,4,"הֲיַעַמְדוּ דִּבְרֵי מָרְדְּכַי. הָאוֹמֵר שֶׁלֹּא יִשְׁתַּחֲוֶה עוֹלָמִית, כִּי הוּא יְהוּדִי, וְהוּזְהַר עַל עֲבוֹדַת אֱלִילִים:",1,0],[3,7,"הִפִּיל פּוּר. הִפִּיל מִי שֶׁהִפִּיל, וְלֹא פִּירֵשׁ מִי. וּמִקְרָא קָצֵר הוּא:",1,0],[3,7,"הוּא הַגּוֹרָל. הַכָּתוּב מְפָרֵשׁ וּמַהוּ הַפּוּר הוּא הַגּוֹרָל. הִפִּיל הַגּוֹרָל בְּאֵיזֶה חֹדֶשׁ יַצְלִיחַ:",2,0],[3,7,"מִיּוֹם לְיוֹם. בְּאֵיזֶה יוֹם בַּחֹדֶשׁ יַצְלִיחַ:",3,0],[3,8,"וְאֶת דָּתֵי הַמֶּלֶךְ. לָתֵת מַס לַעֲבוֹדַת הַמֶּלֶךְ:",1,0],[3,8,"אֵין שֹׁוֶה. אֵין חֲשַׁשׁ. כְּלוֹמַר אֵין בֶּצַע:",2,0],[3,9,"יִכָּתֵב לְאַבְּדָם. יִכָּתֵב סְפָרִים לִשְׁלֹחַ לְשָׂרֵי הַמְּדִינוֹת לְאַבְּדָם:",1,0],[3,10,"וַיָּסַר הַמֶּלֶךְ אֶת טַבַּעְתּוֹ. הוּא מַתַּן כָּל דָּבָר גָּדוֹל שֶׁיִּשְׁאֲלוּ מֵאֵת הַמֶּלֶךְ, לִהְיוֹת מִי שֶׁהַטַּבַּעַת בְּיָדוֹ שַׁלִּיט בְּכָל דְּבַר הַמֶּלֶךְ:",1,0],[3,13,"וְנִשְׁלוֹחַ סְפָרִים. וְיִהְיוּ נִשְׁלָחִים אישטר\"א טרמי\"ש בלע\"ז. וְהוּא מִגִּזְרַת \"אִם נִלְחוֹם נִלְחַם\" נִלְחוֹם, \"הַנִגְלֹה נִגְלֵיתִי\" נִגְלֹה, \"נִדְמֹה נִדְמֵיתִי\": נִדְמֹה:",1,0],[3,13,"בִּשְׁלוֹשָׁה עָשָׂר לְחֹדֶשׁ שְׁנֵים עָשָׂר. בְּיוֹם י\"ג לְאוֹתוֹ חֹדֶשׁ שֶׁהוּא י\"ב לְחָדְשֵׁי הַשָנָה:",2,0],[3,14,"פַּתְשֶׁגֶן. לָשׁוֹן אֲרַמִּי פַּתְשֶׁגֶן סִפּוּר הַכְּתָב דרישמאנ\"ט בְּלַעַ\"ז:",1,0],[3,14,"לְהִנָּתֵן דָּת. צִוּוּי הַכְּתָב שֶׁהָיָה אוֹמֵר לְהִנָּתֵן חֹק גְּזֵרַת הַמֶּלֶךְ:",2,0],[3,14,"גָּלוּי לְכָל הָעַמִּים. דָּבָר זֶה:",3,0],[3,15,"וְהַדָּת נִתְּנָה בְּשׁוּשַׁן. מָקוֹם שֶׁהָיָה הַמֶּלֶךְ שָׁם נִתַּן הַחֹק בּוֹ בַיּוֹם, לִהְיוֹת עֲתִידִים לְיוֹם י\"ג לְחֹדֶשׁ אֲדָר. לְכַךְ,",1,0],[3,15,"וְהָעִיר שׁוּשָׁן נָבוֹכָה. הַיְּהוּדִים שֶׁבָּהּ:",2,0],[4,1,"וּמָרְדְּכַי יָדַע. בַּעַל הַחֲלוֹם אָמַר לוֹ שֶׁהִסְכִּימוּ הָעֶלְיוֹנִים עַל כָּךְ לְפִי שֶׁהִשְׁתַּחֲווּ לַצֶּלֶם בִּימֵי נְבוּכַדְנֶצַר וְשֶׁנֶּהֱנוּ מִסְּעוּדַת אֲחַשְׁוֵרוֹשׁ:",1,0],[4,2,"כִּי אֵין לָבוֹא. אֵין דֶּרֶךְ אֶרֶץ לָבוֹא אֶל שַׁעַר הַמֶּלֶךְ בִּלְבוּשׁ שָׂק:",1,0],[4,3,"דְּבַר הַמֶּלֶךְ וְדָתוֹ. כְּשֶׁהַשְּׁלוּחִים נוֹשְׂאֵי הַסְּפָרִים עוֹבְרִים שָׁם נִתְּנָה הַדָּת בָּעִיר:",1,0],[4,7,"פָּרָשַׁת הַכֶּסֶף. פֵּרוּשׁ הַכֶּסֶף:",1,0],[4,13,"אַל תְּדַמִּי בְנַפְשֵׁךְ. אַל תַּחְשְׁבִי, כְּמוֹ \"וְהָיָה כַּאֲשֶׁר דִּמִּיתִי\". \"אַל תְּדַמִּי בְנַפְשֵׁךְ\": \"אַל תְּהִי סְבוּרָה לְהִמָּלֵט בְּיוֹם הַהֲרֵגָה בְּבֵית הַמֶּלֶךְ, שֶׁאֵין אַתְּ רוֹצָה לְסַכֵּן אֶת עַצְמֵךְ עַכְשָׁיו עַל הַסָּפֵק לָבֹא אֶל הַמֶּלֶךְ שֶׁלֹּא בִרְשׁוּת\":",1,0],[4,14,"וּמִי יוֹדֵעַ אִם לְעֵת כָּזֹאת הִגַּעַתְּ לַמַּלְכוּת. וּמִי יוֹדֵעַ אִם יַחְפֹּץ בָּךְ הַמֶּלֶךְ לַשָּׁנָה הַבָּאָה שֶׁהוּא זְמַן הַהֲרֵגָה:",1,0],[4,14,"לְעֵת כָּזֹאת. שֶׁהוּא הָיָה עוֹמֵד בְּנִיסָן וּזְמַן הַהֲרֵגָה בַּאֲדָר לַשָּׁנָה הַבָּאָה:",2,0],[4,14,"הִגַּעַתְּ לַמַּלְכוּת. אִם תַּגִּיעִי לִגְדֻלָּה שֶׁאַתְּ בָּהּ עַכְשָׁיו:",3,0],[4,16,"אֲשֶׁר לֹא כַדָּת. שֶׁאֵין דָּת לִכָּנֵס אֲשֶׁר לֹא יִקָּרֵא. וּמִדְרַשׁ אַגָּדָה: \"אֲשֶׁר לֹא כַדָּת\" שֶׁעַד עַתָּה בְאֹנֶס וְעַכְשָׁיו בְּרָצוֹן:",1,0],[4,16,"וְכַאֲשֶׁר אָבַדְתִּי אָבָדְתִּי. וְכַאֲשֶׁר הִתְחַלְתִּי לֵילֵךְ לְאִבּוּד אֵלֵךְ וְאָמוּת. וּמִדְרַשׁ אַגָּדָה: כַּאֲשֶׁר אָבַדְתִּי מִבֵּית אַבָּא אֹבַד מִמֶּךָ, שֶׁמֵּעַכְשָׁיו שֶׁאֲנִי בְרָצוֹן נִבְעֶלֶת לְעַכּוּ\"ם, אֲנִי אֲסוּרָה לְךָ:",2,0],[4,17,"וַיַּעֲבֹר מָרְדְּכָי. עַל דָּת, לְהִתְעַנּוֹת בְּיוֹם טוֹב רִאשׁוֹן שֶׁל פֶּסַח, שֶׁהִתְעַנָּה י\"ד בְּנִיסָן וְט\"ו וְט\"ז, שֶׁהֲרֵי בְּיוֹם י\"ג נִכְתְּבוּ הַסְּפָרִים:",1,0],[5,1,"מַלְכוּת. בִּגְדֵי מַלְכוּת. וְרַבּוֹתֵינוּ אָמְרוּ: שֶׁלְּבָשַׁתָּה רוּחַ הַקֹּדֶשׁ, כְּמָה דְּאַתְּ אָמַר \"וְרוּחַ לָבְשָׁה אֶת עֲמָשַׂי\":",1,0],[5,3,"עַד חֲצִי הַמַּלְכוּת. דָּבָר שֶׁהוּא בְאֶמְצַע וּבַחֲצִי הַמַּלְכוּת. הוּא בֵית הַמִּקְדָּשׁ, שֶׁהִתְחִילוּ לִבְנוֹתוֹ בִּימֵי כֹרֶשׁ, וְחָזַר בּוֹ וְצִוָּה לְבַטֵּל הַמְּלָאכָה. וַאֲחַשְׁוֵרוֹשׁ שֶׁעָמַד אַחֲרָיו גַּם הוּא בִּטֵּל הַמְּלָאכָה. וּפְשׁוּטוֹ שֶׁל מִקְרָא: אַף אִם תִּשְׁאֲלִי מִמֶּנִּי חֲצִי הַמַּלְכוּת, אֶתֵּן לָךְ:",1,0],[5,4,"יָבוֹא הַמֶּלֶךְ וְהָמָן. רַבּוֹתֵינוּ אָמְרוּ טְעָמִים הַרְבֵּה בַדָּבָר: מָה רָאֲתָה אֶסְתֵּר שֶׁזִּמְּנָה אֶת הָמָן כְּדֵי לְקַנְאוֹ בַּמֶּלֶךְ וּבַשָּׂרִים, שֶׁהַמֶּלֶךְ יַחְשֹׁב שֶׁהוּא חוֹשֵׁק אֵלֶיהָ וְיַהַרְגֶנּוּ, וְעוֹד טְעָמִים רַבִּים:",1,0],[5,4,"אֶל הַמִּשְׁתֶּה. כָּל סְעוּדָה נִקְרֵאת עַל שֵׁם הַיַּיִן שֶׁהוּא עִיקָר:",2,0],[5,8,"וּמָחָר אֶעֱשֶׂה כִּדְבַר הַמֶּלֶךְ. מַה שֶּׁבִּקַּשְׁתָּ מִמֶּנִּי כָּל הַיָּמִים, לְגַלּוֹת לְךָ אֶת עַמִּי וְאֶת מוֹלַדְתִּי:",1,0],[5,10,"וַיִּתְאַפַּק. נִתְחַזֵּק לַעֲמֹד עַל כַּעְסוֹ, כִּי הָיָה יָרֵא לְהִנָּקֵם בְּלֹא רְשׁוּת. וַיִּתְאַפַּק אישטנט\"ר בְּלַעַ\"ז:",1,0],[5,13,"אֵינֶנּוּ שֹׁוֶה לִי. אֵינִי חָשׁ לְכָל הַכָּבוֹד אֲשֶׁר לִי:",1,0],[5,13,"בְּכָל עֵת וגו'. אָמְרוּ רַבּוֹתֵינוּ שֶׁהָיָה מַרְאֶה לוֹ שְׁטַר שֶׁמָּכַר עַצְמוֹ לְעֶבֶד עַל חֹסֶר מְזוֹנוֹת כְּשֶׁנִּתְמַנּוּ רָאשֵׁי גְיָסוֹת מָרְדְּכַי וְהָמָן בְּמִלְחָמָה אַחַת:",2,0],[6,1,"נָדְדָה שְׁנַת הַמֶּלֶךְ. נֵס הָיָה. וְיֵשׁ אוֹמְרִים שָׂם אֶת לִבּוֹ עַל שֶׁזִּמְּנָה אֶסְתֵּר אֶת הָמָן שֶׁמָּא נָתְנָה עֵינֶיהָ בּוֹ וְיַהַרְגֵהוּ:",1,0],[6,1,"לְהָבִיא אֶת סֵפֶר הַזִּכְרֹנוֹת. דֶּרֶךְ הַמְּלָכִים, כְּשֶׁשְּׁנָתָן נוֹדֶדֶת, אוֹמְרִים לִפְנֵיהֶם מְשָׁלִים וְשִׂיחוֹת עַד שֶׁשְּׁנָתָם חוֹזֶרֶת עֲלֵיהֶם. וְרַבּוֹתֵינוּ אָמְרוּ: מִתּוֹךְ שֶׁנָּתַן לִבּוֹ עַל הָמָן וְאֶסְתֵּר, אָמַר: \"אִי אֶפְשָׁר שֶׁלֹּא יֵדַע אָדָם שֶׁהוּא אוֹהֲבִי עֲצָתָם, וִיגַלֶּה לִי\". וְחָזַר וְאָמַר: \"שֶׁמָּא עָשָׂה לִי אָדָם טוֹבָה וְלֹא גְמַלְתִּיו, וְאֵין חוֹשְׁשִׁין עוֹד לִי\". לְפִיכָךְ, \"וַיֹּאמֶר לְהָבִיא אֶת סֵפֶר הַזִּכְרֹנוֹת\":",2,0],[6,9,"וְנָתוֹן הַלְּבוּשׁ וְהַסּוּס עַל יַד אִישׁ. וְאֶת הַכֶּתֶר לֹא הִזְכִּיר, שֶׁרָאָה עֵינוֹ שֶׁל מֶלֶךְ רָעָה עַל שֶׁאָמַר שֶׁיִּתְּנוּ הַכֶּתֶר בְּרֹאשׁ אָדָם:",1,0],[6,12,"וַיָּשָׁב מָרְדְּכַי. לְשַׂקּוֹ וּלְתַעֲנִיתוֹ:",1,0],[6,12,"אָבֵל וַחֲפוּי רֹאשׁ. רַבּוֹתֵינוּ פֵּרְשׁוּ הַדָּבָר בְּמַסֶּכֶת מְגִילָּה:",2,0],[6,13,"אֲשֶׁר הַחִלּוֹתָ לִנְפֹּל וגו'. אָמְרָה: אֻמָּה זוּ נִמְשְׁלוּ לְכוֹכָבִים וּלְעָפָר. כְּשֶׁהֵם יוֹרְדִים יוֹרְדִים עַד לֶעָפָר, וּכְשֶׁהֵם עוֹלִים עוֹלִים עַד לָרָקִיעַ וְעַד הַכּוֹכָבִים:",1,0],[7,3,"תִּנָּתֶן לִי נַפְשִׁי. שֶׁלֹּא אֵהָרֵג בִּשְׁלשָׁה עָשָׂר בַּאֲדָר שֶׁגָּזַרְתָּ גְזֵרַת הֲרֵגָה עַל עַמִּי וּמוֹלַדְתִּי:",1,0],[7,3,"וְעַמִּי. יִנָּתֵן לִי \"בְּבַקָּשָׁתִי\" שֶׁלֹּא יֵהָרְגוּ. וְאִם תּאמַר: מָה אִכְפַּת לָךְ? \"כִּי אֵיכָכָה אוּכַל וְרָאִיתִי, וגו'\":",2,0],[7,4,"כִּי אֵין הַצָּר שֹׁוֶה בְּנֵזֶק הַמֶּלֶךְ. אֵינֶנּוּ חוֹשֵׁשׁ בְּנֵזֶק הַמֶּלֶךְ שֶׁאִלּוּ רָדַף אַחַר הֲנָאָתְךָ, הָיָה לוֹ לוֹמַר: מְכֹר אוֹתָם לַעֲבָדִים וְלִשְׁפָחוֹת וְקַבֵּל הַמָּמוֹן אוֹ הַחֲיֵה אוֹתָם לִהְיוֹת לְךָ לַעֲבָדִים הֵם וְזַרְעָם:",1,0],[7,5,"וַיֹּאמֶר הַמֶּלֶךְ אֲחַשְׁוֵרוֹשׁ וַיֹּאמֶר לְאֶסְתֵּר הַמַּלְכָּה. כָּל מָקוֹם שֶׁנֶּאֱמַר: \"וַיֹּאמֶר, וַיֹּאמֶר\" שְׁנֵי פְעָמִים, אֵינוֹ אֶלָּא לְמִדְרָשׁ, וּמִדְרָשׁוֹ שֶׁל זֶה: בַּתְּחִלָּה הָיָה מְדַבֵּר עִמָּהּ עַל יְדֵי שָׁלִיחַ. עַכְשָׁיו שֶׁיָּדַע שֶׁמִּמִּשְׁפַּחַת מְלָכִים הִיא, דִּבֵּר עִמָּהּ הוּא בְעַצְמוֹ:",1,0],[7,7,"כִּי כָלְתָה. נִגְמְרָה הָרָעָה וְהַשִּׂנְאָה וְהַנְּקָמָה:",1,0],[7,8,"וְהָמָן נֹפֵל. הַמַּלְאָךְ דְּחָפוֹ:",1,0],[7,8,"עַל הַמִּטָּה אֲשֶׁר אֶסְתֵּר עָלֶיהָ. דַּרְכָּן הָיָה לֵישֵׁב בִּסְעוּדָה עַל צִדָּן עַל גַּבֵּי הַמִּטּוֹת, כְּמוֹ שֶׁנֶּאֱמַר בְּרֹאשׁ הַסֵּפֶר: \"מִטּוֹת זָהָב וָכֶסֶף\" לִבְנֵי הַמִּשְׁתֶּה:",2,0],[7,8,"הֲגַם לִכְבּוֹשׁ. לְשׁוֹן תֵּמַהּ הוּא. לִכְבּוֹשׁ לֶאֱנוֹס בְּחָזְקָה, כְּמוֹ \"וְנִכְבְּשָׁה הָאָרֶץ\":",3,0],[7,9,"גַּם הִנֵּה הָעֵץ. \"גַּם\" רָעָה אַחֶרֶת עָשָׂה שֶׁהֵכִין הָעֵץ לִתְלוֹת אוֹהֲבוֹ שֶׁל מֶלֶךְ שֶׁהִצִּיל הַמֶּלֶךְ מִסַּם הַמָּוֶת:",1,0],[8,1,"מָה הוּא לָהּ. אֵיךְ הוּא קָרוֹב לָהּ:",1,0],[8,3,"לְהַעֲבִיר אֶת רָעַת הָמָן. שֶׁלֹּא תִתְקַיֵּם עֲצָתוֹ הָרָעָה:",1,0],[8,7,"הִנֵּה בֵית הָמָן וגו'. וּמֵעַתָּה הַכֹּל רוֹאִים שֶׁאֲנִי חָפֵץ בָּכֶם, וְכָל מַה שֶׁתֹּאמְרוּ יַאֲמִינוּ הַכֹּל שֶׁמֵּאִתִּי הוּא. לְפִיכָךְ, אֵין צְרִיכִין אַתֶּם לַהֲשִׁיבָם, אֶלָּא \"כִּתְבוּ\" סְפָרִים אֲחֵרִים \"כַּטּוֹב בְּעֵינֵיכֶם\":",1,0],[8,8,"אֵין לְהָשִׁיב. אֵין נָאֶה לַהֲשִׁיבוֹ וְלַעֲשׂוֹת כְּתַב הַמֶּלֶךְ בְּזִיּוּף:",1,0],[8,9,"כִּכְתָבָהּ. בָּאוֹתִיּוֹת שֶׁלָּהּ:",1,0],[8,9,"כִּלְשֹׁנוֹ. הוּא הַדִּבּוּר:",2,0],[8,10,"בְּיַד הָרָצִים. רוֹכְבֵי סוּסִים שֶׁצִּוָּה לָהֶם לָרוּץ:",1,0],[8,10,"הָאֲחַשְׁתְּרָנִים. מִין גְּמַלִּים הַמְמַהֲרִים לָרוּץ:",2,0],[8,11,"וּשְׁלָלָם לָבוֹז. כַּאֲשֶׁר נִכְתַּב בָּרִאשׁוֹנוֹת וְהֵם בַּבִּזָּה לֹא שָׁלְחוּ אֶת יָדָם, שֶׁהֶרְאוּ לַכֹּל שֶׁלֹּא נַעֲשָׂה לְשֵׁם מָמוֹן:",1,0],[8,13,"פַּתְשֶׁגֶן. אִגֶּרֶת מְפֹרָשׁ:",1,0],[8,14,"מְבֹהָלִים. מְמַהֲרִים אוֹתָם לַעֲשׂוֹת מְהֵרָה, לְפִי שֶׁלֹּא הָיָה לָהֶם פְּנַאי, שֶׁהָיָה לָהֶם לְהַקְדִּים רָצִים הָרִאשׁוֹנִים לְהַעֲבִירָם:",1,0],[8,15,"וְתַכְרִיךְ בּוּץ. מַעֲטֵה בוּץ, טַלִּית הֶעָשׂוּי לְהִתְעַטֵּף:",1,0],[8,17,"מִתְיַהֲדִים. מִתְגַּיְּרִים:",1,0],[9,3,"וְעֹשֵׂי הַמְּלָאכָה. אוֹתָם שֶׁהָיוּ מְמֻנִּים לַעֲשׂוֹת צָרְכֵי הַמֶּלֶךְ:",1,0],[9,10,"עֲשֶׂרֶת בְּנֵי הָמָן. רָאִיתִי בְסֵדֶר עוֹלָם אֵלּוּ י' שֶׁכָּתְבוּ שִׂטְנָה עַל יְהוּדָה וִירוּשָׁלָיִם כְּמוֹ שֶׁכָּתוּב בְּסֵפֶר עֶזְרָא \"וּבְמַלְכוּת אֲחַשְׁוֵרוֹשׁ בִּתְחִלַּת מַלְכוּתוֹ כָּתְבוּ שִׂטְנָה עַל ישְׁבֵי יְהוּדָה וִירוּשָׁלָיִם\". וּמָה הִיא הַשִׂטְנָה? לְבַטֵּל הָעוֹלִים מִן הַגּוֹלָה בִּימֵי כוֹרֶשׁ, שֶׁהִתְחִילוּ לִבְנוֹת אֶת הַבַּיִת וְהִלְשִׁינוּ עֲלֵיהֶם הַכּוּתִים וְהֶחֱדִילוּם וּכְשֶׁמֵּת כּוֹרֶשׁ וּמָלַךְ אֲחַשְׁוֵרוֹשׁ וְהִתְנַשֵׂא הָמָן, דָּאַג שֶׁלֹּא יַעַסְקוּ אוֹתָן שֶׁבִּירוּשָׁלַיִם בַּבִּנְיָן וְשָׁלְחוּ בְשֵׁם אֲחַשְׁוֵרוֹשׁ לְשָׂרֵי עֵבֶר הַנָּהָר לְבַטְּלָן:",1,0],[9,10,"וּבַבִּזָּה לֹא שָׁלְחוּ אֶת יָדָם. שֶׁלֹּא יִתֵּן הַמֶּלֶךְ עַיִן צָרָה בַּמָּמוֹן:",2,0],[9,13,"וְאֵת עֲשֶׂרֶת בְּנֵי הָמָן יִתְלוּ עַל הָעֵץ. אוֹתָן שֶׁנֶּהֶרְגוּ:",1,0],[9,14,"וַתִּנָּתֵן דָּת. נִגְזַר חֹק מֵאֵת הַמֶּלֶךְ:",1,0],[9,19,"הַפְּרָזִים. שֶׁאֵינָם יוֹשְׁבִים בְּעָרֵי חוֹמָה בְּאַרְבָּעָה עָשָׂר, וּמֻקָּפִין חוֹמָה בְּט\"ו כְּשׁוּשַׁן. וְהֶקֵּף זֶה צָרִיךְ שֶׁיִּהְיֶה מִימוֹת יְהוֹשֻׁעַ בִּן נוּן. כַּךְ דָּרְשׁוּ וְלָמְדוּ רַבּוֹתֵינוּ:",1,0],[9,19,"וּמִשְׁלֹחַ. שֵׁם דָּבָר, וּמִשְׁלֹחַ, כְּמוֹ מִשְׁמָר מִשְׁמָע לְפִיכָךְ הַשִׁי\"ן נְקוּדָה רָפִי:",2,0],[9,20,"וַיִּכְתּב מָרְדְּכַי. הִיא הַמְּגִלָּה הַזֹּאת כְּמוֹת שֶׁהִיא:",1,0],[9,24,"כִּי הָמָן בֶּן הַמְּדָתָא. חָשַׁב לְהֻמָּם וּלְאַבְּדָם:",1,0],[9,25,"וּבְבֹאָהּ. אֶסְתֵּר אֶל הַמֶּלֶךְ לְהִתְחַנֶּן לוֹ:",1,0],[9,25,"אָמַר עִם הַסֵּפֶר. אָמַר הַמֶּלֶךְ בְּפִיו וְצִוָּה לִכְתֹּב סְפָרִים שֶׁתָּשׁוּב מַחֲשַׁבְתּוֹ הָרָעָה בְרֹאשׁוֹ:",2,0],[9,26,"עַל כֵּן עַל כָּל דִּבְרֵי הָאִגֶּרֶת הַזֹּאת. נִקְבְּעוּ הַיָּמִים הָאֵלֶּה וּלְכַךְ נִכְתְּבָה לָדַעַת דּוֹרוֹת הַבָּאִים:",1,0],[9,26,"וּמָה רָאוּ. עוֹשֵׂי הַמַּעֲשִׂים הָאֵלֶּה שֶׁעֲשָׂאוּם:",2,0],[9,26,"וּמָה הִגִּיעַ אֲלֵיהֶם. מָה רָאָה אֲחַשְׁוֵרוֹשׁ שֶׁנִּשְׁתַּמֵּשׁ בִּכְלֵי הַקֹּדֶשׁ, \"וּמָה הִגִּיעַ אֲלֵיהֶם\": שֶׁבָּא שָׂטָן וְרָקַד בֵּינֵיהֶם וְהָרַג אֶת וַשְׁתִּי. מָה רָאָה הָמָן שֶׁנִּתְקַנֵּא בְמָרְדְּכַי, וּמָה הִגִּיעַ אֵלָיו: שֶׁתָּלוּ אוֹתוֹ וְאֶת בָּנָיו. מָה רָאָה מָרְדְּכַי שֶׁלֹּא יִכְרַע וְלֹא יִשְׁתַּחֲוֶה, וּמָה רָאֲתָה אֶסְתֵּר שֶׁזִּמְּנָה לְהָמָן:",3,0],[9,27,"הַנִּלְוִים עֲלֵיהֶם. גֵּרִים הָעֲתִידִים לְהִתְגַּיֵּר:",1,0],[9,27,"כִּכְתָבָם. שֶׁתְּהֵא הַמְּגִלָּה כְתוּבָה כְּתָב אַשׁוּרִית:",2,0],[9,28,"נִזְכָּרִים. בִּקְרִיאַת הַמְּגִלָּה:",1,0],[9,28,"וְנַעֲשִׂים. מִשְׁתֶּה וְשִׂמְחָה וְיוֹם טוֹב לָתֵת מָנוֹת וּמַתָּנוֹת:",2,0],[9,28,"מִשְׁפָּחָה וּמִשְׁפָּחָה. מִתְאַסְּפִין יַחַד וְאוֹכְלִים וְשׁוֹתִים יָחַד. וְכַךְ קִבְּלוּ עֲלֵיהֶם שֶׁיְּמֵי הַפּוּרִים לֹא יַעַבְרוּ:",3,0],[9,28,"וְזִכְרָם. קְרִיאַת מְגִלָּה:",4,0],[9,28,"לֹא יָסוּף. תַּרְגּוּם שֶׁל יִתֹּם, דִמְתַרְגֵּם עַד תֹּם, עַד דְּסָף. וְאִי אֶפְשָׁר לוֹמַר לִהְיוֹת מִגִּזְרַת \"פֶּן תִּסָּפֶה\" וּמִגִּזְרַת \"עַתָּה אֶסָּפֶה יוֹם אֶחָד\", שֶׁאִם כֵּן, הָיָה לוֹ לִכְתֹּב: \"לֹּא יִסָּפֶה מִזַּרְעָם\":",5,0],[9,29,"אֶת כָּל תֹּקֶף. תָּקְפּוֹ שֶׁל נֵס, שֶׁל אֲחַשְׁוֵרוֹשׁ וְשֶׁל הָמָן וְשֶׁל מָרְדְּכַי וְשֶׁל אֶסְתֵּר:",1,0],[9,29,"הַשֵׁנִית. לַשָׁנָה הַשְׁנִיָּה חָזְרוּ וְשָׁלְחוּ סְפָרִים שֶׁיַּעֲשׂוּ פּוּרִים:",2,0],[9,32,"וּמַאֲמַר אֶסְתֵּר קִיַּם וגו'. אֶסְתֵּר בִּקְשָׁה מֵאֵת חַכְמֵי הַדּוֹר לְקָבְעָהּ וְלִכְתֹּב סֵפֶר זֶה עִם שְׁאָר הַכְּתוּבִים. וְזֶהוּ \"וְנִכְתָּב בַּסֵּפֶר\":",1,0],[10,3,"לְרֹב אֶחָיו. וְלֹא לְכָל אֶחָיו, מְלַמֵּד שֶׁפֵּרְשׁוּ מִמֶּנּוּ מִקְצַת סַנְהֶדְרִין, לְפִי שֶׁנַּעֲשָׂה קָרוֹב לַמַּלְכוּת וְהָיָה בָטֵל מִתַּלְמוּדוֹ:",1,0],[10,3,"לְכָל זַרְעוֹ. מֻסָּב עַל עַמּוֹ לְכָל זֶרַע עַמּוֹ:",2,0]]);
